(()=>{'use strict';if(window.__radarPrototypeVersionV221)return;window.__radarPrototypeVersionV221=true;function install(){if(document.getElementById('radarVersionBadgeV221'))return true;const postos=document.getElementById('fuelChip');if(!postos)return false;const b=document.createElement('div');b.id='radarVersionBadgeV221';b.textContent='V 221';Object.assign(b.style,{position:'fixed',zIndex:'99999',font:'700 11px Arial',padding:'3px 7px',borderRadius:'8px',background:'rgba(7,19,31,.88)',color:'#fff',pointerEvents:'none'});document.body.appendChild(b);const place=()=>{const r=postos.getBoundingClientRect();b.style.left=Math.round(r.left+r.width/2-b.offsetWidth/2)+'px';b.style.top=Math.round(r.bottom+5)+'px'};place();addEventListener('resize',place);return true}let n=0,t=setInterval(()=>{if(install()||++n>200)clearInterval(t)},100);})();